import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address depositor, address collector) public {
        // Restrict to plausible domain
        vm.assume(depositor != address(0) && collector != address(0));
        vm.assume(depositor != collector);
        bound(depositAmount, 1, 1 ether);
        bound(collectAmount, 1, 1 ether);

        // Initialize and set minimum
        c.Initialized();
        c.SetMinSum(0);

        // Deposit from depositor
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Track total deposits
        uint256 totalDeposits = depositAmount;

        // Collect from collector (who has no balance, but contract may have balance from depositor)
        // Collector will fail if trying to collect, so we use try/catch
        bool successCollect;
        vm.prank(collector);
        try c.Collect(collectAmount) { successCollect = true; } catch { successCollect = false; }

        // Sum of all balances + contract balance
        uint256 sumBalances = c.balances(depositor) + c.balances(collector);
        uint256 contractBalance = address(c).balance;
        uint256 collectedAmount = successCollect ? collectAmount : 0;

        // General rule: total deposits - successful collects = sum of all balances + contract balance
        assertTrue(totalDeposits - collectedAmount == sumBalances + contractBalance);
    }
}

