pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // Helper that reverts on receiving ETH, forcing a failed Collect
    contract RevertingCollector {
        fallback() external payable { revert(); }
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address caller, address other) public {
        // Keep amounts reasonable and non-zero for meaningful test
        bound(depositAmount, 1, 100 ether);
        bound(collectAmount, 1, 100 ether);
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(this)); // Log interactions are irrelevant, but we need Log to not revert
        c.Initialized();

        // Deploy a helper that will revert on collect, testing a failed withdrawal
        RevertingCollector badCollector = new RevertingCollector();
        address collectorTarget = other;

        // Deposit for the caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record pre-state for the invariant
        uint256 initialBalance = c.balances(caller);

        // Perform a Collect that will succeed in transferring ETH (the low-level call succeeds to a regular address)
        // We first do a successful Collect to observe balance changes in normal case.
        vm.prank(caller);
        uint256 beforeCollectBalance = c.balances(caller);
        uint256 beforeTargetBalance = c.balances(collectorTarget);

        // We need collectAmount <= balance to satisfy the contract condition
        vm.assume(collectAmount <= beforeCollectBalance);

        // The helper 'badCollector' makes the low-level call fail, we use that to test revert path.
        // First successful Collect path: use a regular address as target
        vm.prank(caller);
        c.Collect(collectAmount);

        // After successful collection, balance should be reduced by collectAmount
        uint256 afterBalanceNormal = c.balances(caller);
        uint256 expectedNormal = beforeCollectBalance - collectAmount;

        // Now test a failing Collect: the contract reverts if transfer fails, so balances unchanged.
        // Deploy an adversarial callee that reverts on receive.
        RevertingCollector revertTarget = new RevertingCollector();
        // We set up a different caller so the fuzzer explores diverse actors,
        // but we use the 'other' address funded for a second test.
        vm.deal(other, depositAmount);
        vm.prank(other);
        c.Deposit{value: depositAmount}();

        uint256 balanceBeforeRevert = c.balances(other);
        vm.assume(collectAmount <= balanceBeforeRevert);

        try c.Collect(collectAmount) returns (bool) {
            // Collect should NOT succeed because transfer will revert
            // If it does succeed, something is wrong.
            // We only assert the main invariant: balance changes are symmetric
        } catch {
            // Expected revert path, balances unchanged
            uint256 balanceAfterRevert = c.balances(other);
            assertEq(balanceAfterRevert, balanceBeforeRevert, "Balance should not change on revert");
        }

        // The main universal invariant: after a successful Collect, the caller's balance decreases by exactly collectAmount.
        // This must hold in the reference. The buggy deposit-decrement can cause the balance to underflow
        // or become inconsistent, so this assert will fail for some fuzzer inputs.
        assertEq(afterBalanceNormal, expectedNormal, "Invariant broken: balance decreased by wrong amount after Collect");
    }
}

