pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address userA, address userB, uint256 depositA, uint256 depositB, uint256 collectA, uint256 collectB) public {
        vm.assume(userA != address(0) && userB != address(0) && userA != userB);
        depositA = bound(depositA, 1, type(uint256).max / 2);
        depositB = bound(depositB, 1, type(uint256).max / 2 - 1);
        collectA = bound(collectA, 0, depositA);
        collectB = bound(collectB, 0, depositB);

        // Setup contract: set MinSum to 0 and initialize
        c.SetMinSum(0);
        // Deploy a dummy LogFile to satisfy the contract (external call in Collect will succeed)
        // We do not need LogFile for the assertion, but Collect calls Log.AddMessage which reverts if Log is zero address.
        // Deploy a minimal empty callee that does not revert.
        EmptyLog log = new EmptyLog();
        c.SetLogFile(address(log));
        c.Initialized();

        // Record initial total sum of balances of userA and userB (both start at 0)
        uint256 initialSum = c.balances(userA) + c.balances(userB);

        // Fund addresses and deposit
        vm.deal(userA, depositA);
        vm.prank(userA);
        c.Deposit{value: depositA}();

        vm.deal(userB, depositB);
        vm.prank(userB);
        c.Deposit{value: depositB}();

        // Now perform collects
        if (collectA > 0) {
            vm.prank(userA);
            c.Collect(collectA);
        }
        if (collectB > 0) {
            vm.prank(userB);
            c.Collect(collectB);
        }

        // Compute current total sum of balances for the two users
        uint256 finalSum = c.balances(userA) + c.balances(userB);

        // Invariant: total sum of balances after deposits and collects never drops below initial sum (which was 0).
        // More precisely, because deposits always add to balances, and collects only move balance to user, the
        // total visible balance of participants should not decrease.
        assertTrue(finalSum >= initialSum);
    }
}

