import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, address collector, uint256 depositAmount, uint256 collectAmount) public {
        // Ensure reasonable amounts to avoid overflow reverts in require
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, type(uint128).max);

        // Avoid using the zero address as a prank actor
        vm.assume(depositor != address(0));
        vm.assume(collector != address(0));
        // Collector must be different from depositor for the invariant to hold generally,
        // but we also keep the deposit/collect relationship: we need to ensure the collector
        // has deposited enough and later calls collect. The invariant is about the depositor's balance.
        // The depositor's balance after deposit must be strictly greater than before.
        // We check the depositor's balance after deposit and after the collector collects.
        // To trigger the bug, we need to call deposit with depositor, then collect with collector
        // who has sufficient balance (the collector must have deposited previously).
        // We set up collector's balance by a second deposit.
        // The buggy version reduces the depositor's balance, making the depositor unable to collect later.
        // We test: depositor deposits, then depositor tries to collect an amount <= deposited. Reference succeeds. Bug reverts.
        // So we fuzz a collector distinct from depositor, but we actually need depositor to collect.
        // Simpler: depositor deposits, then depositor collects the full deposit amount. Reference succeeds, bug reverts.
        // No adversarial helper needed.

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0x1));
        c.Initialized();

        // Fund depositor
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Record depositor's balance after deposit
        uint256 depositorBalance = c.balances(depositor);

        // Deposit the same amount for collector to ensure it has enough balance
        // We need collector to be able to call Collect if the test requires it, but here
        // we only need depositor to call Collect. The previous failed attempts used a different invariant.
        // The simplest invariant: after a successful deposit, the sender's balance strictly increases.
        // The require is checked, but the mutation subtracts, so the balance decreases.
        // We check: depositor balance after deposit >= depositAmount.
        // Reference: balances[depositor] = depositAmount; Bug: balances[depositor] = 0 (if it was 0 before).
        // So assert that balances[depositor] >= depositAmount.

        assertTrue(depositorBalance >= depositAmount);
    }
}

